for (int i = 0; i < numDocs; i++) {
    int groupId = 0;
    for (int j = _numGroupByExpressions - 1; j >= 0; j--) {
        groupId = groupId * _cardinalities[j] + _singleValueDictIds[j][i];
    }
    outGroupIds[i] = groupId;
    if (!_flags[groupId]) {        // line 348 — groupId can be >= _flags.length
        _numKeys++;
        _flags[groupId] = true;
    }
